pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _lockTime, uint256 _putAmount, uint256 _collectAmount) public {
        // Bound inputs to avoid overflow and underflow issues in the reference
        _minSum = bound(_minSum, 0, 10000);
        _lockTime = bound(_lockTime, 0, 10000);
        _putAmount = bound(_putAmount, 0, 10000);
        _collectAmount = bound(_collectAmount, 0, 10000);

        // Ensure the contract has enough balance to cover the potential collect
        vm.deal(address(this), 20000);

        // Set MinSum before initialization
        c.SetMinSum(_minSum);

        // Initialize the contract
        c.Initialized();

        // Deposit some ether
        c.Put{value: _putAmount}(_lockTime);

        // Record MinSum before Collect
        uint256 beforeMinSum = c.MinSum();

        // Attempt Collect; it may revert depending on conditions, but we only care when it succeeds
        // To ensure it succeeds, we need: balance >= MinSum, balance >= _collectAmount, block.timestamp > unlockTime
        // Also the contract must have enough ether to send; we deal it manually
        // We prank as the contract itself to have balance for the call
        vm.deal(address(c), _collectAmount);
        // Advance time past unlock time
        vm.warp(block.timestamp + _lockTime + 1);

        // The caller must be the address that put the funds; for simplicity, we use the test contract address
        // But Put was called by this contract, so the holder is this contract. Collect must be called by same.
        // However, vm.deal gave ether to the contract, not to this address; Collect sends from contract balance to msg.sender.
        // To avoid complications, we use vm.startPrank to make the call as the contract itself? No, msg.sender must be the holder.
        // Since we called Put as this contract, the holder is address(this). We'll call Collect from address(this).
        // But Collect sends ether to msg.sender; we need the contract to have ether to send. We already dealt ether to the contract.
        // The contract balance check in Collect is for the holder's balance, not the contract's overall balance.
        // The holder's balance is acc.balance, which was increased by Put. That is separate from the contract's ether balance.
        // Collect sends ether from the contract to msg.sender. It requires the contract to have enough ether.
        // We deal ether to the contract so it has enough.
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _collectAmount));

        if (success) {
            uint256 afterMinSum = c.MinSum();
            assertTrue(beforeMinSum == afterMinSum, "MinSum changed after successful Collect");
        }
    }
}

