pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit, uint256 lockTime, uint256 collectAmount) public {
        // Restrict inputs to avoid reverts in the reference
        vm.assume(deposit > 0 && deposit <= 1e24);
        vm.assume(collectAmount > 0 && collectAmount <= deposit);
        vm.assume(lockTime <= 1e9);

        // Set minimal sum to 0 and initialize
        c.SetMinSum(0);
        c.Initialized();

        // Fund caller and make a deposit via Put
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Put{value: deposit}(lockTime);

        // Warp time past lock
        vm.warp(block.timestamp + lockTime + 1);

        // Record history length before Collect
        uint256 historyBefore = c.Log().HistoryLength();

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 500000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The general rule: If Collect succeeded and Log contract exists, history length increases by exactly 1;
        // but Log is never set in the buggy version (Log defaults to address(0)), so the call to Log.AddMessage in Collect
        // will revert silently (address(0).call returns false but does not revert inside the if).
        // In the buggy version, the internal call fails and history length remains unchanged.
        // In the reference version, Log is set to a real LogFile contract, so the call succeeds and history increments.

        // We check: history length changed by exactly 1 if and only if Log is set (i.e., there is a Log contract at the address)
        address logAddr = address(c.Log());
        bool logIsSet = (logAddr != address(0));
        uint256 historyAfter = c.Log().HistoryLength();

        // The property: if Collect succeeded and log is set, history must have increased by 1.
        // If log is not set, the call to Log.AddMessage will fail (due to low-level call returning false),
        // but the collect still succeeds (since the if checks the return and doesn't revert).
        // So history shouldn't change.
        bool historyChanged = (historyAfter == historyBefore + 1);
        bool property = (success && logIsSet) ? historyChanged : true;
        assertTrue(property);
    }
}

