import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, uint256 initialBalance, uint256 lockTime, uint256 minSum) public {
        // bounds to ensure Collect can succeed logically
        vm.assume(initialBalance > 0 && initialBalance <= type(uint128).max);
        vm.assume(am > 0 && am < initialBalance);
        vm.assume(lockTime > 0 && lockTime <= type(uint40).max);
        vm.assume(minSum > 0 && minSum <= initialBalance);

        // Do NOT call SetLogFile
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the contract so it has balance
        vm.deal(address(c), initialBalance);

        // Prepare a user
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        // User must have a deposit that passes the conditions
        c.Put{value: initialBalance}(lockTime);

        // Warp time past unlock
        vm.warp(block.timestamp + lockTime + 1);

        uint256 balanceBefore = address(c).balance;

        vm.prank(user);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", am));

        uint256 balanceAfter = address(c).balance;

        // The rule: if SetLogFile was never called, Collect should not be able to send out Ether
        // because the reentrancy guard combined with the missing Log assignment means the external call
        // in Collect will revert due to call to Log.AddMessage on a zero-address Log
        assertTrue(balanceAfter == balanceBefore, "Balance changed despite Log not being set");
    }
}

