        uint256 balanceBefore = c.Acc(caller).balance;
        uint256 unlockTime = c.Acc(caller).unlockTime;

        // Advance time to a random point relative to unlockTime
        uint256 timeShift = bound(uint256(keccak256(abi.encode(block.timestamp, lockTime))), 0, 2 * lockTime + 1000);
        if (block.timestamp < unlockTime && timeShift <= unlockTime - block.timestamp) {
            vm.warp(block.timestamp + timeShift);
        } else {
            vm.warp(block.timestamp + unlockTime + 10); // ensure past unlockTime
        }
        bool timestampPast = block.timestamp > unlockTime;

        // Call Collect
        vm.prank(caller);
        c.Collect(collectAmount);

        // Check: balance decreased only if timestamp condition held
        uint256 balanceAfter = c.Acc(caller).balance;
        bool balanceDecreased = balanceAfter < balanceBefore;
        // The reference ensures balance only decreases if block.timestamp > unlockTime
        assertTrue(!balanceDecreased || timestampPast, "Balance decreased without timestamp condition");
    }
}

